package com.edgeos.launcher; import android.service.notification.NotificationListenerService;import android.service.notification.StatusBarNotification;import android.content.*;import android.os.*;import android.provider.Settings;import android.graphics.*;import android.view.*;import android.widget.*;
public class NotificationService extends NotificationListenerService{static int count=0;WindowManager wm;View island;Handler h=new Handler();public void onNotificationPosted(StatusBarNotification s){count++;showIsland(s.getPackageName());}void showIsland(String pkg){if(!Settings.canDrawOverlays(this))return;h.post(()->{try{if(island!=null)wm.removeView(island);}catch(Exception ignored){}TextView t=Ui.text(this,"●  "+pkg,13,Color.WHITE);t.setPadding(24,0,24,0);t.setBackground(Ui.bg(Color.BLACK,60));island=t;wm=(WindowManager)getSystemService(WINDOW_SERVICE);WindowManager.LayoutParams p=new WindowManager.LayoutParams(-2,Ui.dp(this,42),Build.VERSION.SDK_INT>=26?WindowManager.LayoutParams.TYPE_APPLICATION_OVERLAY:WindowManager.LayoutParams.TYPE_PHONE,WindowManager.LayoutParams.FLAG_NOT_FOCUSABLE|WindowManager.LayoutParams.FLAG_LAYOUT_NO_LIMITS,PixelFormat.TRANSLUCENT);p.gravity=Gravity.TOP|Gravity.CENTER_HORIZONTAL;p.y=Ui.dp(this,12);wm.addView(island,p);h.postDelayed(()->{try{if(island!=null)wm.removeView(island);island=null;}catch(Exception ignored){}},3500);});}public void onNotificationRemoved(StatusBarNotification s){count=Math.max(0,count-1);}}
